ALTER TABLE px_self_certificate_links ADD COLUMN IF NOT EXISTS input_hash VARCHAR(64);
CREATE OR REPLACE FUNCTION guard_px_self_certificate_links() RETURNS trigger AS 'BEGIN IF to_jsonb(NEW.input_hash) IS DISTINCT FROM to_jsonb(OLD.input_hash) OR to_jsonb(NEW.id) IS DISTINCT FROM to_jsonb(OLD.id) OR to_jsonb(NEW.owner_account_id) IS DISTINCT FROM to_jsonb(OLD.owner_account_id) OR to_jsonb(NEW.event_id) IS DISTINCT FROM to_jsonb(OLD.event_id) OR to_jsonb(NEW.event_name_snapshot) IS DISTINCT FROM to_jsonb(OLD.event_name_snapshot) OR to_jsonb(NEW.model_name_snapshot) IS DISTINCT FROM to_jsonb(OLD.model_name_snapshot) OR to_jsonb(NEW.revision_id) IS DISTINCT FROM to_jsonb(OLD.revision_id) OR to_jsonb(NEW.public_id) IS DISTINCT FROM to_jsonb(OLD.public_id) OR to_jsonb(NEW.key_version) IS DISTINCT FROM to_jsonb(OLD.key_version) OR to_jsonb(NEW.public_token_hash) IS DISTINCT FROM to_jsonb(OLD.public_token_hash) OR to_jsonb(NEW.share_text_snapshot) IS DISTINCT FROM to_jsonb(OLD.share_text_snapshot) OR to_jsonb(NEW.config_hash) IS DISTINCT FROM to_jsonb(OLD.config_hash) OR to_jsonb(NEW.idempotency_key) IS DISTINCT FROM to_jsonb(OLD.idempotency_key) OR to_jsonb(NEW.created_at) IS DISTINCT FROM to_jsonb(OLD.created_at) THEN RAISE EXCEPTION ''SELF_CERTIFICATE_IMMUTABLE'' USING ERRCODE = ''23514''; END IF; RETURN NEW; END;' LANGUAGE plpgsql;
